@startuml

class RealEstateAgency {
  + Search(key: string): void
}

class Property {
  + Code: string
  + Address: string
  + ZipCode: string
  + City: string
  + Area: int
  + toString(): string
}

class Garage extends Property {
}

class Apartment extends Property {
  + Rooms: int
  + Bathrooms: int
}

class Villa extends Apartment {
  + GardenSize: int
}

RealEstateAgency "1" -- "*" Property : manages

@enduml

